CREATE OR REPLACE FUNCTION public.save_new_workspace_context(p_workspace uuid,p_context jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN UPDATE public.workspaces SET website=CASE WHEN COALESCE(website,'')='' THEN nullif(left(p_context->>'website',600),'') ELSE website END,industry=CASE WHEN COALESCE(industry,'') IN ('','أخرى','عام') THEN COALESCE(nullif(left(p_context->>'industry',120),''),industry) ELSE industry END,profile=COALESCE(profile,'{}'::jsonb)||jsonb_build_object('welcome',p_context-'website') WHERE id=p_workspace AND owner_id=auth.uid() AND created_at>now()-interval '10 minutes' AND NOT COALESCE(profile,'{}'::jsonb) ? 'welcome'; END $$;